/**
 * A short text hint shown on hover or focus (`design/components/tooltip.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tooltip.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/tooltip'
import { normalizeProps } from '@zag-js/solid'

import {
  TOOLTIP_DELAY_MS,
  TOOLTIP_SKIP_DELAY_MS,
  afresh,
  anchorProps,
  claimSlot,
  closeTooltipOnScroll,
  createDerived,
  elementRef,
  holdTooltipFromPointer,
  mergeParts,
  scope,
  syncTriggerAnchor,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/tooltip.module.css'

export type TooltipAlign = NonNullable<TooltipProps['align']>

export type TooltipSide = NonNullable<TooltipProps['side']>

export interface TooltipProps {
  align?: 'start' | 'center' | 'end'
  /**
   * One focusable element; a tooltip on a disabled control can never be read.
   */
  children: JSX.Element
  content: string
  /**
   * Opens on mount, for galleries and tests.
   */
  defaultOpen?: boolean
  side?: 'bottom' | 'top' | 'right' | 'left'
}

/** A short text hint shown on hover or focus. */
export default function Tooltip(given: TooltipProps): JSX.Element {
  const props = mergeProps(
    { side: 'top', align: 'center' } as Defaults<TooltipProps, 'side' | 'align'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const anchor = elementRef<HTMLElement>()
    const bubble = elementRef<HTMLElement>()
    const documentDirection = useDirection(() => anchor.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          defaultOpen: props.defaultOpen,
          openDelay: TOOLTIP_DELAY_MS,
          closeDelay: TOOLTIP_SKIP_DELAY_MS,
          closeOnScroll: false,
          positioning: {
            placement: props.align === 'center' ? props.side : `${props.side}-${props.align}`,
            gutter: 0,
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const present = usePresence(
      () => api.value.open,
      () => bubble.value,
      'tooltip.bubble',
      {
        get side() {
          return props.side
        },
        get align() {
          return props.align
        },
      },
    )
    const effect1 = () => {
      syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open, false)
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect1,
      true,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = closeTooltipOnScroll(api.value.open ? anchor.value : null, () =>
        api.value.setOpen(false),
      )
      release2 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect2,
      true,
    )
    onCleanup(() => release2?.())
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = holdTooltipFromPointer(anchor.value)
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <>
        {/* trigger */}
        <span
          {...mergeParts(anchorProps(api.value.getTriggerProps()), {
            class: styles.anchor,
            'data-tooltip-part': 'trigger',
          })}
          ref={anchor.attach}
        >
          {props.children}
        </span>
        <Portal>
          {afresh(() => (
            <>
              {present() ? (
                <div {...mergeParts(api.value.getPositionerProps())}>
                  {/* bubble */}
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.bubble,
                      style: {
                        '--radix-tooltip-content-available-width': 'var(--available-width)',
                      },
                      hidden: undefined,
                      'data-state': api.value.open ? 'delayed-open' : 'closed',
                      'data-member': 'tooltip',
                    })}
                    ref={bubble.attach}
                  >
                    {props.content}
                  </div>
                </div>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
